package com.medicare360.doctor; import jakarta.persistence.*; @Entity public class Doctor { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private String name; private String specialization; private String email; private String phone; public Long getId(){return id;} public String getName(){return name;} public void setName(String v){name=v;} public String getSpecialization(){return specialization;} public void setSpecialization(String v){specialization=v;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public String getPhone(){return phone;} public void setPhone(String v){phone=v;} }